import{_ as i,a0 as p,w as d,s as o,I as t,x as e,a1 as n,A as l,ao as c}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"Rust 基礎系列 #6: 條件語句 | LCTT x X-CMD","titleTemplate":false,"description":"Rust 基礎系列 #6: 條件語句 | LCTT (202306) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Rust 基礎系列 #6: 條件語句 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Rust 基礎系列 #6: 條件語句 | LCTT (202306) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202306/20230501.1 ⭐️⭐️ Rust Basics Series 6 Conditional Statements","title":"Rust 基礎系列 #6: 條件語句","tag":"202306","desc":""},"relativePath":"202306/20230501.1 ⭐️⭐️ Rust Basics Series 6 Conditional Statements.md","filePath":"[post].md"}'),r={name:"202306/20230501.1 ⭐️⭐️ Rust Basics Series 6 Conditional Statements.md"};function g(h,s,b,f,u,k){const a=p("Link");return d(),o("div",null,[s[18]||(s[18]=t("h1",{id:"rust-基礎系列-6-條件語句",tabindex:"-1"},[e("Rust 基礎系列 #6: 條件語句 "),t("a",{class:"header-anchor",href:"#rust-基礎系列-6-條件語句","aria-label":"Permalink to “Rust 基礎系列 #6: 條件語句”"},"​")],-1)),s[19]||(s[19]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/202306/11/094832bkkbs7oxntx7zxas.jpg",alt:""})],-1)),t("p",null,[s[1]||(s[1]=e("在 ",-1)),n(a,{href:"https://linux.cn/article-15855-1.html"},{default:l(()=>[...s[0]||(s[0]=[e("上一篇文章",-1)])]),_:1}),s[2]||(s[2]=e(" 中，你學習了函數。在這篇文章中，我們將學習使用條件語句來管理 Rust 程序的控制流。",-1))]),s[20]||(s[20]=c(`<h3 id="什麼是條件語句" tabindex="-1">什麼是條件語句？ <a class="header-anchor" href="#什麼是條件語句" aria-label="Permalink to “什麼是條件語句？”">​</a></h3><p>在編寫代碼的時候，最常見的任務之一就是檢查某些條件是否為 <code>true</code> 或 <code>false</code>。“如果温度高於 35°C，打開空調。”</p><p>通過使用 <code>if</code> 和 <code>else</code> 這樣的關鍵字（有時候結合使用），程序員可以根據條件（例如提供的參數數量、從命令列傳遞的選項、文件名、錯誤發生等）改變程序的行為。</p><p>所以，對一個程序員來説，瞭解任何語言的控制流都是至關重要的，更不用説 Rust 了。</p><h4 id="條件運算符" tabindex="-1">條件運算符 <a class="header-anchor" href="#條件運算符" aria-label="Permalink to “條件運算符”">​</a></h4><p>下表列出了所有常用的單個條件運算符：</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">運算符</th><th style="text-align:left;">示例</th><th style="text-align:left;">解釋</th></tr></thead><tbody><tr><td style="text-align:left;"><code>&gt;</code></td><td style="text-align:left;"><code>a &gt; b</code></td><td style="text-align:left;"><code>a</code> <strong>大於</strong> <code>b</code></td></tr><tr><td style="text-align:left;"><code>&lt;</code></td><td style="text-align:left;"><code>a &lt; b</code></td><td style="text-align:left;"><code>a</code> <strong>小於</strong> <code>b</code></td></tr><tr><td style="text-align:left;"><code>==</code></td><td style="text-align:left;"><code>a == b</code></td><td style="text-align:left;"><code>a</code> <strong>等於</strong> <code>b</code></td></tr><tr><td style="text-align:left;"><code>!=</code></td><td style="text-align:left;"><code>a != b</code></td><td style="text-align:left;"><code>a</code> <strong>不等於</strong> <code>b</code></td></tr><tr><td style="text-align:left;"><code>&gt;=</code></td><td style="text-align:left;"><code>a &gt;= b</code></td><td style="text-align:left;"><code>a</code> <strong>大於</strong> 或 <strong>等於</strong> <code>b</code></td></tr><tr><td style="text-align:left;"><code>&lt;=</code></td><td style="text-align:left;"><code>a &lt;= b</code></td><td style="text-align:left;"><code>a</code> <strong>小於</strong> 或 <strong>等於</strong> <code>b</code></td></tr></tbody></table></div><p>以及下表是邏輯運算符，它們用於一個或多個條件之間：</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">運算符</th><th style="text-align:left;">示例</th><th style="text-align:left;">解釋</th></tr></thead><tbody><tr><td style="text-align:left;">\`</td><td style="text-align:left;"></td><td style="text-align:left;">\` （邏輯或）</td></tr><tr><td style="text-align:left;"><code>&amp;&amp;</code> （邏輯與）</td><td style="text-align:left;"><code>條件1 &amp;&amp; 條件2</code></td><td style="text-align:left;"><strong>所有</strong> 條件都為 <code>true</code></td></tr><tr><td style="text-align:left;"><code>!</code> （邏輯非）</td><td style="text-align:left;"><code>!條件</code></td><td style="text-align:left;"><code>條件</code> 的布爾值的相反值</td></tr></tbody></table></div><blockquote><p>📋 與數學相似，你可以使用圓括號來指定操作的優先級。</p></blockquote><h3 id="使用-if-else" tabindex="-1">使用 if else <a class="header-anchor" href="#使用-if-else" aria-label="Permalink to “使用 if else”">​</a></h3><p>要控制 Rust 代碼的基本流程，使用兩個關鍵字：<code>if</code> 和 <code>else</code>。這可以根據提供的條件的狀態創建兩個“執行路徑”。</p><p>一個簡單的帶有替代執行路徑的 if 塊的語法如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if 條件 {</span></span>
<span class="line"><span>    &lt;語句&gt;;</span></span>
<span class="line"><span>} else {</span></span>
<span class="line"><span>    &lt;語句&gt;;</span></span>
<span class="line"><span>}</span></span></code></pre></div><blockquote><p>📋 當只有一個條件時，將其括在圓括號中並不是強制性的。根據語法，使用圓括號是可選的。你仍然應該使用它們來指定優先級並優化可讀性。</p></blockquote><p>來看看一個例子。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fn main() {</span></span>
<span class="line"><span>    let a = 36;</span></span>
<span class="line"><span>    let b = 25;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    if a &gt; b {</span></span>
<span class="line"><span>        println!(&quot;a 大於 b&quot;);</span></span>
<span class="line"><span>    } else {</span></span>
<span class="line"><span>        println!(&quot;b 大於 a&quot;);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>這裏，我聲明瞭兩個整數變量 <code>a</code> 和 <code>b</code>，它們的值分別為 &#39;36&#39; 和 &#39;25&#39;。在第 5 行，我檢查變量 <code>a</code> 中存儲的值是否大於變量 <code>b</code> 中存儲的值。如果條件計算結果為 <code>true</code>，則會執行第 6 行的代碼。如果條件計算結果為 <code>false</code>，由於我們有一個 <code>else</code> 塊（可選），第 8 行的代碼將被執行。</p><p>來看看程序的輸出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>a 大於 b</span></span></code></pre></div><p>完美！</p><p>來修改一下變量 <code>a</code> 的值，使其小於變量 <code>b</code> 的值，看看會發生什麼。我將把 <code>a</code> 的值改為 &#39;10&#39;。修改後的輸出如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>b 大於 a</span></span></code></pre></div><p>但是，如果我將相同的值存儲在變量 <code>a</code> 和 <code>b</code> 中呢？為了看到這一點，我將兩個變量的值都設置為 &#39;40&#39;。修改後的輸出如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>b 大於 a</span></span></code></pre></div><p>嗯？從邏輯上講，這沒有任何意義... 😦</p><p>但是這可以改進！我們繼續。</p><h3 id="使用-else-if-條件" tabindex="-1">使用 else if 條件 <a class="header-anchor" href="#使用-else-if-條件" aria-label="Permalink to “使用 else if 條件”">​</a></h3><p>與其他任何編程語言一樣，你可以使用 <code>else if</code> 塊來提供多於兩個的執行路徑。語法如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if 條件 {</span></span>
<span class="line"><span>    &lt;語句&gt;;</span></span>
<span class="line"><span>} else if 條件 {</span></span>
<span class="line"><span>    &lt;語句&gt;;</span></span>
<span class="line"><span>} else {</span></span>
<span class="line"><span>    &lt;語句&gt;;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>現在，通過使用 <code>else if</code> 塊，我可以改進程序的邏輯。下面是修改後的程序。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fn main() {</span></span>
<span class="line"><span>    let a = 40;</span></span>
<span class="line"><span>    let b = 40;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    if a == b {</span></span>
<span class="line"><span>        println!(&quot;a 與 b 是相等的&quot;);</span></span>
<span class="line"><span>    } else if a &gt; b {</span></span>
<span class="line"><span>        println!(&quot;a 大於 b&quot;);</span></span>
<span class="line"><span>    } else {</span></span>
<span class="line"><span>        println!(&quot;b 大於 a&quot;);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>現在，我的程序的邏輯是正確的。它已經處理了所有的邊緣情況（我能想到的）。第 5 行處理了 <code>a</code> 等於 <code>b</code> 的情況。第 7 行處理了 <code>a</code> 可能大於 <code>b</code> 的情況。而 <code>a</code> 小於 <code>b</code> 的情況則由第 9 行的 <code>else</code> 塊隱式處理。</p><p>現在，當我運行這段代碼時，我得到了以下輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>a 與 b 是相等的</span></span></code></pre></div><p>現在這就完美了！</p><h3 id="示例-找到最大值" tabindex="-1">示例：找到最大值 <a class="header-anchor" href="#示例-找到最大值" aria-label="Permalink to “示例：找到最大值”">​</a></h3><p>我知道使用 <code>if</code> 和 <code>else</code> 很容易，但是讓我們再看一個程序。這次，我們來比較三個數字。我還將在這個實例中使用邏輯運算符！</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fn main() {</span></span>
<span class="line"><span>    let a = 73;</span></span>
<span class="line"><span>    let b = 56;</span></span>
<span class="line"><span>    let c = 15;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    if (a != b) &amp;&amp; (a != c) &amp;&amp; (b != c) {</span></span>
<span class="line"><span>        if (a &gt; b) &amp;&amp; (a &gt; c) {</span></span>
<span class="line"><span>            println!(&quot;a 是最大的&quot;);</span></span>
<span class="line"><span>        } else if (b &gt; a) &amp;&amp; (b &gt; c) {</span></span>
<span class="line"><span>            println!(&quot;b 是最大的&quot;);</span></span>
<span class="line"><span>        } else {</span></span>
<span class="line"><span>            println!(&quot;c 是最大的&quot;);</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>這個程序第一眼看上去可能很複雜，但是不要害怕，我會解釋的！</p><p>最開始，我聲明瞭三個變量 <code>a</code>、<code>b</code> 和 <code>c</code>，並賦予了我能想到的隨機值。然後，在第 6 行，我檢查了沒有變量的值與其他變量相同的條件。首先，我檢查 <code>a</code> 和 <code>b</code> 的值，然後是 <code>a</code> 和 <code>c</code>，最後是 <code>b</code> 和 <code>c</code>。這樣我就可以確定沒有變量中存儲了重複的值。</p><p>然後，在第 7 行，我檢查了變量 <code>a</code> 中存儲的值是否是最大的。如果這個條件計算結果為 <code>true</code>，則會執行第 8 行的代碼。否則，將檢查第 9 行的執行路徑。</p><p>在第 9 行，我檢查了變量 <code>b</code> 中存儲的值是否是最大的。如果這個條件計算結果為 <code>true</code>，則會執行第 10 行的代碼。如果這個條件也是 <code>false</code>，那麼只有一種可能。3 個變量中的最大值既不是 <code>a</code> 也不是 <code>b</code>。</p><p>所以，自然地，在 <code>else</code> 塊中，我打印出變量 <code>c</code> 擁有最大值。</p><p>來看看程序的輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>a 是最大的</span></span></code></pre></div><p>這是預期的結果。嘗試修改分配給每個變量的值，並自己測試一下！ 😃</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>你學習到了如何使用 <code>if</code> 和 <code>else</code> 語句。在你繼續使用大量 <code>if</code> <code>else if</code> 語句製作自己的 AI 之前（哈哈），讓我們在本系列的下一篇文章中學習 Rust 中的循環。</p><p>持續關注。</p><p><em>（題圖：MJ/3eea3bbb-b630-4470-ae21-391ab86cd5bf）</em></p><hr>`,52)),t("p",null,[s[4]||(s[4]=e("via: ",-1)),n(a,{href:"https://itsfoss.com/rust-if-else/"},{default:l(()=>[...s[3]||(s[3]=[e("https://itsfoss.com/rust-if-else/",-1)])]),_:1})]),t("p",null,[s[9]||(s[9]=e("作者：",-1)),n(a,{href:"https://itsfoss.com/author/pratham/"},{default:l(()=>[...s[5]||(s[5]=[e("Pratham Patel",-1)])]),_:1}),s[10]||(s[10]=e(" 選題：",-1)),n(a,{href:"https://github.com/lkxed/"},{default:l(()=>[...s[6]||(s[6]=[e("lkxed",-1)])]),_:1}),s[11]||(s[11]=e(" 譯者：",-1)),n(a,{href:"https://github.com/Cubik65536"},{default:l(()=>[...s[7]||(s[7]=[e("Cubik65536",-1)])]),_:1}),s[12]||(s[12]=e(" 校對：",-1)),n(a,{href:"https://github.com/wxy"},{default:l(()=>[...s[8]||(s[8]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[15]||(s[15]=e("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[13]||(s[13]=[e("LCTT",-1)])]),_:1}),s[16]||(s[16]=e(" 原創編譯，",-1)),n(a,{href:"https://linux.cn/"},{default:l(()=>[...s[14]||(s[14]=[e("Linux中國",-1)])]),_:1}),s[17]||(s[17]=e(" 榮譽推出",-1))])])}const C=i(r,[["render",g]]);export{y as __pageData,C as default};
